    internal static void AddCategory(Faction f, UnitCategory cat, List<int> into)
    {
      if (f.TryGetObjectByCategory(cat, out var ids) && ids != null)
      {
        for (var i = 0; i < ids.Count; i++)
        {
          into.Add(ids[i]);
        }
      }
    }

    internal static bool ListHas(List<int> list, int v)
    {
      for (var i = 0; i < list.Count; i++)
      {
        if (list[i] == v)
        {
          return true;
        }
      }

      return false;
    }

    private static readonly Dictionary<string, float> _heroRefused = new(); // 0.38: "pid|hero" -> retry time

    private static void TrainSome(unit building, List<int> pool)
    {
      for (var i = 0; i < QueuePerBuilding; i++)
      {
        IssueImmediateOrderById(building, pool[GetRandomInt(0, pool.Count - 1)]);
      }
    }

    // Heroes train at Altars by unit-type. No public API maps an UNtrained hero to its faction, so we read
    // faction-correct ids from AiConfig (source-derived) -- no id spray. Trains any config hero the bot
    // lacks alive (a dead one gets revived instead), one per altar per cycle, gold-gated; WC3's hero limit
    // self-caps. Fallback: a faction missing from AiConfig simply trains no heroes (no crash, no spray).
    // 0.38: new heroes are FREE for bots with perks (like researches and upgrades: AiTech.FreeOrder tops up the gold
    // for the order only). A bot without perks (fair autopilot) pays and returns true = SAVE gold this turn when an
    // available hero is too expensive. Candidates: AiConfig.Heroes (priority order, e.g. Arthas first), then every
    // other hero this altar trains (AiData.AltarHeroes). A hero WC3 refuses anyway is skipped for 5 min.
    private static bool TrainHeroes(unit altar, Faction faction, player p)
    {
      if (GetUnitCurrentOrder(altar) != 0)
      {
        return false; // altar already training or reviving something
      }

      var cand = new List<int>();
      if (AiConfig.Heroes.TryGetValue(faction.Name, out var ids) && ids != null)
      {
        for (var i = 0; i < ids.Count; i++)
        {
          cand.Add(ids[i]);
        }
      }

      var atid = GetUnitTypeId(altar);
      if (AiData.AltarHeroes.ContainsKey(atid))
      {
        var more = AiData.AltarHeroes[atid];
        for (var i = 0; i < more.Length; i++)
        {
          if (!ListHas(cand, more[i]))
          {
            cand.Add(more[i]);
          }
        }
      }

      var pid = GetPlayerId(p);
      for (var i = 0; i < cand.Count; i++)
      {
        var hid = cand[i];
        if (PermaDead.Contains(hid))
        {
          continue; // v28: died permanently (e.g. Cenarius) -- WL would adopt a re-trained copy, so never train it
        }

        if (HaveLiveHero(p, hid) || !RequirementsMet(p, hid))
        {
          continue; // already alive, or still locked (quest not done)
        }

        var key = I2S(pid) + "|" + I2S(hid);
        if (_heroRefused.ContainsKey(key) && _clock < _heroRefused[key])
        {
          continue;
        }

        var perks = HasPerks(p);
        if (perks ? AiTech.FreeOrder(p, altar, hid) : IssueImmediateOrderById(altar, hid))
        {
          return false; // trained a new hero, or revived a dead one; one per altar per cycle
        }

        if (!perks && GetPlayerState(p, PLAYER_STATE_RESOURCE_GOLD) < GetUnitGoldCost(hid))
        {
          return true; // available but too expensive right now -> save
        }

        _heroRefused[key] = _clock + 300f; // refused for another reason (limit, hero cap ...)
      }

      return false;
    }

    // 0.38: all requirements of a unit/hero type met (AiData.Requires: researches or unit types)
    internal static bool RequirementsMet(player p, int typeId)
    {
      if (!AiData.Requires.ContainsKey(typeId))
      {
        return true;
      }

      var req = AiData.Requires[typeId];
      for (var i = 0; i < req.Length; i++)
      {
        if (GetPlayerTechCount(p, req[i], false) < 1)
        {
          return false;
        }
      }

      return true;
    }

    // 0.38: train from the building's REAL list (AiData.Trains): only types whose requirements are met, the type
    // this bot has trained least first (random among equals) -> an even mix instead of random category pools.
    private static void TrainFromTable(unit building, int[] list, player p)
    {
      var pid = GetPlayerId(p);
      var avail = new List<int>();
      for (var i = 0; i < list.Length; i++)
      {
        if (RequirementsMet(p, list[i]))
        {
          avail.Add(list[i]);
        }
      }

      var queued = 0;
      var tries = 0;
      while (queued < QueuePerBuilding && avail.Count > 0 && tries < 6)
      {
        tries++;
        var start = GetRandomInt(0, avail.Count - 1);
        var best = -1;
        var bestN = 0;
        for (var k = 0; k < avail.Count; k++)
        {
          var idx = (start + k) % avail.Count;
          var n = AiStats.Count(pid, avail[idx]);
          if (best < 0 || n < bestN)
          {
            best = idx;
            bestN = n;
          }
        }

        var t = avail[best];
        if (IssueImmediateOrderById(building, t))
        {
          queued++;
          AiStats.Planned(pid, t); // counts the order, so the next slot picks another type
        }
        else
        {
          avail.RemoveAt(best); // not possible right now (gold, food, limit) -> try another type
        }
      }
    }

    private static bool HaveLiveHero(player p, int heroType)
    {
      // 0.37: a later form of the same legend counts too (AiConfig.HeroForms: Arthas UEAR -> N023 after "The
      // Ascension"), otherwise the bot would train the first form again
      var later = AiConfig.HeroForms.ContainsKey(heroType) ? AiConfig.HeroForms[heroType] : 0;
      var all = LegendaryHeroManager.GetAll();
      for (var i = 0; i < all.Count; i++)
      {
        var hu = all[i].Unit;
        if (hu != null && (all[i].UnitType == heroType || (later != 0 && all[i].UnitType == later))
            && GetOwningPlayer(hu) == p && GetUnitState(hu, UNIT_STATE_LIFE) > 0.405f)
        {
          return true;
        }
      }

      return false;
    }

    // v13: bring back bots' dead (non-perma) heroes for free every few minutes, at their start location.
    // Bots are too gold-starved to pay altar revive costs, so heroes were staying dead.
    // 0.35.3: the bot's living altar nearest to (x, y), or null
    internal static unit FindAltar(player p, float x, float y)
    {
      var fac = p.GetPlayerData().Faction;
      if (fac == null)
      {
        return null;
      }

      var altarTypes = new List<int>();
      AddCategory(fac, UnitCategory.Altar, altarTypes);
      unit best = null;
      var bestD = 0f;
      var g = CreateGroup();
      GroupEnumUnitsOfPlayer(g, p, null);
      unit u;
      while ((u = FirstOfGroup(g)) != null)
      {
        GroupRemoveUnit(g, u);
        if (!altarTypes.Contains(GetUnitTypeId(u)) || GetUnitState(u, UNIT_STATE_LIFE) <= 0.405f
            || BlzIsUnitInvulnerable(u) && IsUnitHidden(u))
        {
          continue;
        }

        var dx = GetUnitX(u) - x;
        var dy = GetUnitY(u) - y;
        var d = dx * dx + dy * dy;
        if (best == null || d < bestD)
        {
          best = u;
          bestD = d;
        }
      }

      DestroyGroup(g);
      return best;
    }

    private static void OnHeroReviveTick()
    {
      if (BotBreak)
      {
        return;
      }

      var heroes = LegendaryHeroManager.GetAll();
      for (var b = 0; b < Bots.Count; b++)
      {
        var p = Bots[b];
        if (!HasPerks(p))
        {
          continue; // 0.35: fair autopilot -- heroes are revived at the altar like a player's
        }

        var loc = GetPlayerStartLocation(p);
        var hx = GetStartLocationX(loc);
        var hy = GetStartLocationY(loc);
        unit altar = null;
        var altarLooked = false;
        for (var i = 0; i < heroes.Count; i++)
        {
          var hu = heroes[i].Unit;
          if (hu == null || GetUnitTypeId(hu) == 0)
          {
            continue; // never had a unit, or WL already removed it (perma-death disposes the unit)
          }

          if (GetOwningPlayer(hu) != p || GetUnitState(hu, UNIT_STATE_LIFE) > 0.405f)
          {
            continue;
          }

          // v28: perma-death guard. 'LEgo' = WL's PermaDies marker ability (readable even though the C# property
          // is set-only); PermaDead = types WL reported as permanently killed. Either -> stays dead.
          if (GetUnitAbilityLevel(hu, PermaDiesMarker) > 0 || PermaDead.Contains(heroes[i].UnitType))
          {
            continue;
          }

          // 0.35.3: only with a living altar, and the hero appears at that altar (nearest to the start location)
          if (!altarLooked)
          {
            altar = FindAltar(p, hx, hy);
            altarLooked = true;
          }

          if (altar == null)
          {
            continue;
          }

          ReviveHero(hu, GetUnitX(altar), GetUnitY(altar), true);
          Log("P" + I2S(GetPlayerId(p)) + " " + FacName(p) + ": free revive " + GetUnitName(hu) + " at " + GetUnitName(altar));
        }
      }
    }

    // v28: subscribe to every registered LegendaryHero's Died event (append-only list -> hook only the new ones;
    // cheap enough to call every production tick, so legends registered mid-game are covered too).
    // v32: also remember each legend's unit type at hook time, so a permanent death blacklists the ORIGINAL form
    // even when WL has already switched the legend to a new form (Cenarius -> ghost) in an earlier handler.
    internal static List<LegendaryHero> _hookedLegends = new();
    private static readonly List<int> _hookedType = new();

    private static void EnsureLegendHooks()
    {
      var all = LegendaryHeroManager.GetAll();
      for (var i = _legendsHooked; i < all.Count; i++)
      {
        all[i].Died += OnLegendDied;
        _hookedLegends.Add(all[i]);
        _hookedType.Add(all[i].UnitType);
      }

      _legendsHooked = all.Count;
    }

    private static void OnLegendDied(LegendDiedEventArgs e)
    {
      var lh = e.LegendaryHero;
      if (!e.Permanent || lh == null)
      {
        return;
      }

      var orig = lh.UnitType;
      for (var i = 0; i < _hookedLegends.Count; i++)
      {
        if (_hookedLegends[i] == lh && _hookedType[i] != 0)
        {
          orig = _hookedType[i];
          break;
        }
      }

      if (orig != 0 && !PermaDead.Contains(orig))
      {
        PermaDead.Add(orig);
        LogPin("PERMA-DEATH " + lh.Name + " (" + I2S(orig) + ") -> excluded from train/revive");
      }

      AiMissions.RemoveBannedForm(lh); // the new form may already exist if WL's handler ran first
    }

    private static void OnProductionTick()
    {
      EnsureLegendHooks();
      if (BotBreak || !ProdOn)
      {
        return;
      }

      if (Bots.Count == 0)
      {
        return;
      }

      if (_prodCursor >= Bots.Count)
      {
        _prodCursor = 0;
      }

      ProdOps = 0;
      var start = _prodCursor;
      _prodCursor++;
      for (var b = start; b == start; b++) // v12: exactly one bot per production tick
      {
        var p = Bots[b];
        var pid0 = GetPlayerId(p);
        var perks = HasPerks(p); // 0.35: false for a FAIR autopilot player -- no subsidy, no free techs/upgrades
        if (perks)
        {
          var gold = GetPlayerState(p, PLAYER_STATE_RESOURCE_GOLD) + GoldBonusFor(p); // v13: subsidy; v31: per faction
          SetPlayerState(p, PLAYER_STATE_RESOURCE_GOLD, gold < 0 ? 0 : gold); // 0.43.1: may be negative (easy votes)
          var techLvl = R2I(_clock / 600f); // v21: 0 before 10 min, then +1 every 10 min
          if (techLvl > 5)
          {
            techLvl = 5;
          }

          for (var ui = 0; ui < AiConfig.CombatUpgrades.Count; ui++)
          {
            SetPlayerTechResearched(p, AiConfig.CombatUpgrades[ui], techLvl);
          }

          // 0.36: food floor. Humans kill a bot's farms and its production stops for good (bots never build).
          // WC3 recomputes the cap whenever a food building is made or lost, so this is re-applied every turn.
          // Only ever raises: a bot with more farms keeps its higher cap.
          if (GetPlayerState(p, PLAYER_STATE_FOOD_CAP_CEILING) < FoodFloor)
          {
            SetPlayerState(p, PLAYER_STATE_FOOD_CAP_CEILING, FoodFloor);
          }

          if (GetPlayerState(p, PLAYER_STATE_RESOURCE_FOOD_CAP) < FoodFloor)
          {
            SetPlayerState(p, PLAYER_STATE_RESOURCE_FOOD_CAP, FoodFloor);
          }
        }

        var faction = p.GetPlayerData().Faction;
        if (faction == null)
        {
          continue;
        }

        // v33: UNIT/ABILITY pool (casters + abilities, AiUpgrades.ByFaction + Extra): steps unlocked =
        // 1 + one per 5 min (old timer) + one per 2 CPs captured. Steps = every upgrade at level 1 first, then
        // level 2, then level 3, so casters reach their higher tiers too.
        var caps = _cpCaptures.ContainsKey(pid0) ? _cpCaptures[pid0] : 0;
        var steps = AiTech.TechStepsFor(faction.Name);
        if (perks && steps.Ids.Count > 0)
        {
          var un = 1 + R2I(_clock / 300f) + caps / 2;
          if (un > steps.Ids.Count)
          {
            un = steps.Ids.Count;
          }

          for (var uk = 0; uk < un; uk++)
          {
            SetPlayerTechResearched(p, steps.Ids[uk], steps.Levels[uk]); // later steps raise the same id further
          }
        }

        // v33: BUILDING/MISC pool -- one credit per 2 CPs captured (no timer); spent after the structure scan.
        var bCredits = perks ? caps / 2 - (_bSpent.ContainsKey(pid0) ? _bSpent[pid0] : 0) : 0;
        unit upHall = null;
        unit upOther = null;

        var barracks = new List<int>();
        AddCategory(faction, UnitCategory.Barracks, barracks);
        var siegeShops = new List<int>();
        AddCategory(faction, UnitCategory.SiegeWorkshop, siegeShops);
        var magicBuildings = new List<int>();
        AddCategory(faction, UnitCategory.Magic, magicBuildings);
        var flyBuildings = new List<int>();
        AddCategory(faction, UnitCategory.FlyingBuilding, flyBuildings);
        var altars = new List<int>();
        AddCategory(faction, UnitCategory.Altar, altars);

        var fighters = new List<int>();
        AddCategory(faction, UnitCategory.Fighter, fighters);
        AddCategory(faction, UnitCategory.Marksman, fighters);
        var siege = new List<int>();
        AddCategory(faction, UnitCategory.Siege, siege);
        AddCategory(faction, UnitCategory.Tank, siege);
        AddCategory(faction, UnitCategory.Destroyer, siege);
        var support = new List<int>();
        AddCategory(faction, UnitCategory.Support, support);
        var flyers = new List<int>();
        AddCategory(faction, UnitCategory.Flyer, flyers);

        var altarUnits = new List<unit>();
        var trainers = new List<unit>();
        var g = CreateGroup();
        GroupEnumUnitsOfPlayer(g, p, null);
        unit u;
        while ((u = FirstOfGroup(g)) != null)
        {
          GroupRemoveUnit(g, u);
          ProdOps++;
          if (!IsUnitType(u, UNIT_TYPE_STRUCTURE))
          {
            continue;
          }

          var tid = GetUnitTypeId(u);
          if (perks)
          {
            AiTech.TryEventResearch(p, u, tid); // v32: event researches first, while the building's queue is free
            AiTech.TryQuestUpgrade(p, u, tid);  // v34: quest building upgrades (Stormwind's Construction Sites)
            AiTech.TryTimedUpgrade(p, u, tid);  // 0.36: timed building upgrades (Fel Horde demon gates)
          }
          if (bCredits > 0 && AiUpgrades.BuildingUpgrades.ContainsKey(tid) && GetUnitState(u, UNIT_STATE_LIFE) > 0.405f)
          {
            if (IsUnitType(u, UNIT_TYPE_TOWNHALL))
            {
              if (upHall == null)
              {
                upHall = u;
              }
            }
            else if (upOther == null)
            {
              upOther = u;
            }
          }

          // 0.38: collect first, train after the loop -- heroes before units (see below)
          if (ListHas(altars, tid) || AiData.AltarHeroes.ContainsKey(tid))
          {
            altarUnits.Add(u);
          }
          else if (AiData.Trains.ContainsKey(tid) || ListHas(barracks, tid) || ListHas(siegeShops, tid)
                   || ListHas(magicBuildings, tid) || ListHas(flyBuildings, tid))
          {
            trainers.Add(u);
          }
        }

        DestroyGroup(g);

        // 0.38: heroes first. If a hero is available (requirements met) but the gold is short, the bot SAVES this
        // turn (no units). Before, units ate all gold every turn: Quel'thalas never had more than ~110 gold, so
        // Rommath / Lor'themar never came although "The Blood Elves" was done.
        var saving = false;
        for (var ai = 0; ai < altarUnits.Count; ai++)
        {
          if (TrainHeroes(altarUnits[ai], faction, p))
          {
            saving = true;
          }
        }

        GetDiag(pid0).Saving = saving;
        for (var ti = 0; ti < trainers.Count && !saving; ti++)
        {
          var tu = trainers[ti];
          var ttid = GetUnitTypeId(tu);
          if (AiData.Trains.ContainsKey(ttid))
          {
            TrainFromTable(tu, AiData.Trains[ttid], p); // 0.38: the building's REAL train list
          }
          else if (fighters.Count > 0 && ListHas(barracks, ttid))
          {
            TrainSome(tu, fighters); // fallback: buildings without a train list in the map data
          }
          else if (siege.Count > 0 && ListHas(siegeShops, ttid))
          {
            TrainSome(tu, siege);
          }
          else if (support.Count > 0 && ListHas(magicBuildings, ttid))
          {
            TrainSome(tu, support);
          }
          else if (flyers.Count > 0 && ListHas(flyBuildings, ttid))
          {
            TrainSome(tu, flyers);
          }
        }
        if (bCredits > 0)
        {
          AiTech.SpendBuildingCredit(p, pid0, upHall, upOther);
        }
      }

      if (ProdOps > MaxProdOps)
      {
        MaxProdOps = ProdOps;
      }
    }

    private static void OnCombatTick()
    {
      _clock += Tick;
      if (BotBreak || Bots.Count == 0)
      {
        return;
      }

      // v8: service exactly ONE bot this tick, then advance the cursor. This is the whole
      // multiplayer fix -- per-second unit enumeration + orders drop ~13x versus v7.
      if (_cursor >= Bots.Count)
      {
        _cursor = 0;
      }

      var p = Bots[_cursor];
      _cursor++; // v26.1: advance BEFORE Process -- if Process ever throws, the cursor still moves on so the
                 // round-robin can't wedge on one bot (the bug that left every bot but P0 doing nothing).
      OpUnits = 0;
      OpOrders = 0;
      DefOps = 0;
      Process(p);
      LastOpUnits = OpUnits;
      LastOpOrders = OpOrders;
      LastDefOps = DefOps;
      if (OpUnits > MaxOpUnits)
      {
        MaxOpUnits = OpUnits;
      }

      if (DefOps > MaxDefOps)
      {
        MaxDefOps = DefOps;
      }
    }

    private static bool ValidTarget(unit u, player p)
    {
      return u != null
             && GetUnitState(u, UNIT_STATE_LIFE) > 0.405f
             && GetOwningPlayer(u) != p
             && !IsUnitAlly(u, p);
    }

    private static void Process(player p)
    {
      var pid = GetPlayerId(p);
      var hasFaction = p.GetPlayerData().Faction != null;
      float bx = 0f, by = 0f;
      var haveBase = false;
      float sumX = 0f, sumY = 0f;
      var army = 0;
      // 0.36: army per landmass (index = landmass + 1; 0 = sea / uncovered cells). The target anchor is the biggest
      // group on real ground, not the centroid of everything -- an army split over two continents had its centroid
      // in the sea and switched targets every few seconds (85-min test: Sentinels 98 on an island + 84 mainland).
      var lmCount = new int[LmSlots];
      var lmX = new float[LmSlots];
      var lmY = new float[LmSlots];
      AiArmy.Units.Clear(); // 0.41: the orderable army, collected in this one pass (no second pass for orders)

      var g = CreateGroup();
      GroupEnumUnitsOfPlayer(g, p, null);
      unit u;
      while ((u = FirstOfGroup(g)) != null)
      {
        GroupRemoveUnit(g, u);
        OpUnits++;
        if (IsUnitType(u, UNIT_TYPE_STRUCTURE))
        {
          if (!haveBase || IsUnitType(u, UNIT_TYPE_TOWNHALL))
          {
            bx = GetUnitX(u);
            by = GetUnitY(u);
            haveBase = true;
          }
        }
        else if (!IsUnitType(u, UNIT_TYPE_PEON))
        {
          army++;
          var ux = GetUnitX(u);
          var uy = GetUnitY(u);
          sumX += ux;
          sumY += uy;
          var slot = Geography.Landmass(ux, uy) + 1;
          if (slot < 0 || slot >= LmSlots)
          {
            slot = 0;
          }

          lmCount[slot]++;
          lmX[slot] += ux;
          lmY[slot] += uy;
          if (u != _ragHero && !AiState.MissionUnits.Contains(u) && GetUnitState(u, UNIT_STATE_LIFE) > 0.405f
              && GetUnitMoveSpeed(u) > 1f)
          {
            AiArmy.Units.Add(u); // 0.41: alive, can move, not on a mission
          }

          if (IsUnitType(u, UNIT_TYPE_HERO))
          {
            HeroGrabItems(u); // v24: only heroes, only on this bot's turn -> effectively free
          }
        }
      }

      DestroyGroup(g);

      float ax, ay;
      if (haveBase)
      {
        ax = bx;
        ay = by;
      }
      else if (army > 0)
      {
        ax = sumX / army;
        ay = sumY / army;
      }
      else
      {
        BotArmy[pid] = 0;
        BotFac[pid] = hasFaction ? 1 : 0;
        BotLm[pid] = -999;
        SetState(p, pid, "idle");
        NoteTarget(p, pid, null, "no-army");
        return;
      }

      // v30: TARGET anchor = where the army actually is (its centroid), not the town hall. Picking "nearest
      // frontier to the base" sent armies that had marched far away back across the map (e.g. Scourge army in
      // Lordaeron re-targeting Borean Tundra in Northrend). Nearest-to-army is also naturally sticky: an army
      // walking toward X keeps X as its nearest frontier. ax/ay (base) is still used for landmass + holding.
      // 0.36: ...of the biggest group on real ground (see lmCount above); sea-only armies fall back to the centroid.
      float tx = ax, ty = ay;
      var anchorUnits = 0;
      if (army > 0)
      {
        var bestSlot = 0;
        for (var k = 1; k < LmSlots; k++)
        {
          if (lmCount[k] > lmCount[bestSlot] || (bestSlot == 0 && lmCount[k] > 0))
          {
            bestSlot = k;
          }
        }

        anchorUnits = lmCount[bestSlot];
        tx = lmX[bestSlot] / anchorUnits;
        ty = lmY[bestSlot] / anchorUnits;
      }

      var diag = GetDiag(pid);
      diag.AnchorX = tx;
      diag.AnchorY = ty;
      diag.AnchorIsBase = army == 0;
      diag.AnchorUnits = anchorUnits;

      var lm = Geography.Landmass(ax, ay);
      var state = "off";

      // v27: ARBITRATION. If an invasion wave is currently mustering or channelling this faction's army, that
      // wave owns the army -- combat yields, so the two systems never issue conflicting orders to the same
      // units. The wave self-aborts (its %/enemy gate) if home is threatened, handing control straight back.
      var facWave = p.GetPlayerData().Faction;
      if (facWave != null && AiWaveRunner.WaveOwnsFaction(facWave.Name))
      {
        BotArmy[pid] = army;
        BotLm[pid] = lm;
        BotFac[pid] = 1;
        SetState(p, pid, "wave");
        NoteTarget(p, pid, null, "wave-owns-army");
        return;
      }

      if (AtkOn)
      {
        // reachability anchor: prefer an owned capital/CP's landmass -- reliable even when the army sits
        // in a grid cell the downsample never covered (this is the Druids "l-1" fix).
        var homeLm = HomeLandmass(p, lm);
        diag.HomeLm = homeLm;

        var defend = AiDefense.Pick(p, pid, tx, ty); // 0.43.2: reach + hysteresis (was FindDefenseTarget(p): anywhere)
        if (defend != null)
        {
          // Rule 0: base/CP under attack -> recall, overriding whatever offense was committed.
          Committed[pid] = defend;
          CommitTime[pid] = _clock;
          state = "def";
          NoteTarget(p, pid, defend, "defend(" + I2S(_defWorst) + " enemy units, " + I2S(_defCreeps) + " neutrals ignored)");
          TrackStuck(p, pid, null);
          IssueAttackToPoint(p, pid, GetUnitX(defend), GetUnitY(defend), true, GetUnitX(defend), GetUnitY(defend));
        }
        else
        {
          // v26: no MinArmy gate any more -- the staging/clash system IS the gathering, so bots always act.
          var handled = false;
          var fac = p.GetPlayerData().Faction;
          BotTargetName[pid] = "-";

          // v31: a scripted kill target (AiConfig.KillTargets, e.g. Scourge -> Sapphiron) outranks expansion until
          // the unit is dead. Whole army attack-moves it; defence above still pre-empts.
          var kill = AiMissions.ActiveKillTarget(p, pid);
          if (kill != null)
          {
            state = "kill";
            BotTargetName[pid] = "K:" + GetUnitName(kill);
            NoteTarget(p, pid, kill, "kill-target");
            TrackStuck(p, pid, null);
            IssueAttackToPoint(p, pid, GetUnitX(kill), GetUnitY(kill), true, GetUnitX(kill), GetUnitY(kill));
            handled = true;
          }

          // 0.42: route planner on the generated graph (-route on, default). From the attack group's centre (or the
          // army's); orders go to the next waypoint. Nothing reachable -> the old frontier picker below.
          if (!handled && fac != null && AiRoutes.On)
          {
            float sx = tx, sy = ty;
            AiArmy.GroupCenter(pid, ref sx, ref sy);
            var rt = AiRoutes.Pick(p, pid, fac, sx, sy, diag);
            if (rt != null)
            {
              var enemyRt = GetPlayerId(GetOwningPlayer(rt)) < 24;
              Committed[pid] = rt;
              CommitTime[pid] = _clock;
              state = "atk";
              BotTargetName[pid] = (enemyRt ? "E:" : "N:") + GetUnitName(rt);
              NoteTarget(p, pid, rt, enemyRt ? "route-enemy" : "route-neutral");
              TrackStuck(p, pid, rt);
              float rx = GetUnitX(rt), ry = GetUnitY(rt);
              if (AiRoutes.HasWaypoint(pid) && !AiRoutes.Chains) // 0.44: chains carry the route themselves
              {
                IssueAttackToPoint(p, pid, AiRoutes.WpX[pid], AiRoutes.WpY[pid], false, rx, ry);
              }
              else
              {
                IssueAttackToPoint(p, pid, rx, ry, false, rx, ry);
              }

              handled = true;
            }
          }

          // authored CP graph -- expand from my frontier to the nearest bordering CP I don't own.
          if (!handled && fac != null)
          {
            var gnode = PickGraphTarget(p, fac, tx, ty, diag);
            if (gnode != null)
            {
              // v28: no staging / clash window any more -- neutral AND enemy frontiers are attacked directly.
              // (Enemy frontiers still can't be returned before 10 min; PickGraphTarget filters them.)
              var enemyCp = IsEnemyCp(gnode, p);
              Committed[pid] = gnode;
              CommitTime[pid] = _clock;
              state = "atk";
              BotTargetName[pid] = (enemyCp ? "E:" : "N:") + GetUnitName(gnode);
              NoteTarget(p, pid, gnode, enemyCp ? "graph-enemy" : "graph-neutral");
              TrackStuck(p, pid, gnode);
              IssueAttackToPoint(p, pid, GetUnitX(gnode), GetUnitY(gnode), false, GetUnitX(gnode), GetUnitY(gnode));
              handled = true;
            }
          }

          if (!handled && fac != null && AiConfig.Doctrine.TryGetValue(fac.Name, out var steps) && steps != null)
          {
            for (var i = 0; i < steps.Count; i++)
            {
              var st = steps[i];
              if (_clock < st.AfterSec || (st.X == 0f && st.Y == 0f))
              {
                continue; // time-gate not open, or unfilled placeholder (fill via -xy)
              }

              if (AreaNeedsAttention(p, st.X, st.Y, ObjectiveRadius))
              {
                Committed[pid] = null;
                state = "atk";
                NoteTarget(p, pid, null, "doctrine-step-" + I2S(i));
                IssueAttackToPoint(p, pid, st.X, st.Y, false, st.X, st.Y);
                handled = true;
                break;
              }
            }
          }

          if (!handled)
          {
            var tgt = Committed[pid];
            if (!ValidTarget(tgt, p) || _clock - CommitTime[pid] > CommitTimeout)
            {
              tgt = PickObjective(p, pid, tx, ty, homeLm);
              Committed[pid] = tgt;
              CommitTime[pid] = _clock;
            }

            if (tgt != null)
            {
              state = "atk";
              BotTargetName[pid] = "F:" + GetUnitName(tgt);
              NoteTarget(p, pid, tgt, "fallback-nearest");
              TrackStuck(p, pid, tgt);
              IssueAttackToPoint(p, pid, GetUnitX(tgt), GetUnitY(tgt), false, GetUnitX(tgt), GetUnitY(tgt));
            }
            else
            {
              state = "hold";
              NoteTarget(p, pid, null, "hold-nothing-reachable");
              if (AiArmy.Smart)
              {
                IssueAttackToPoint(p, pid, ax, ay, true, ax, ay); // 0.41: hold throttled like any target (was: every service)
              }
              else
              {
                Gather(p, ax, ay); // nothing reachable -> hold at home
              }
            }
          }
        }
      }
      else
      {
        NoteTarget(p, pid, null, "atk-off");
      }

      BotArmy[pid] = army;
      BotLm[pid] = lm;
      BotFac[pid] = hasFaction ? 1 : 0;
      SetState(p, pid, state);
    }

    // v28: state/target bookkeeping for diagnostics. Logs CHANGES only.
    private static void SetState(player p, int pid, string state)
    {
      var old = BotState.ContainsKey(pid) ? BotState[pid] : "-";
      if (old != state)
      {
        Log("P" + I2S(pid) + " " + FacName(p) + ": state " + old + " -> " + state);
        if (pid >= 0 && pid < 24 && old != "-")
        {
          AiScheduler.StateSwitch[pid]++; // 0.44
        }
      }

      BotState[pid] = state;
    }

    private static void NoteTarget(player p, int pid, unit tgt, string reason)
    {
      var d = GetDiag(pid);
      if (d.Target != tgt)
      {
        var from = d.Target != null ? GetUnitName(d.Target) : "-";
        var to = tgt != null ? GetUnitName(tgt) : "-";
        Log("P" + I2S(pid) + " " + FacName(p) + ": target " + from + " -> " + to + " [" + reason + "]");
        if (pid >= 0 && pid < 24)
        {
          AiScheduler.TargetSwitch[pid]++; // 0.44
        }
        d.Target = tgt;
        d.TargetSince = _clock;
      }

      d.Reason = reason;
    }

    // nearest reachable enemy/unowned capital (Scourge only) -- attack-move clears the yard
    // v9: pick the best reachable objective -- enemy/neutral CONTROL POINTS first (income), then CAPITALS.
    // Attack-moving to the anchor clears the yard en route; the commit persists until it's captured/timeout.
    private static unit PickObjective(player p, int pid, float ax, float ay, int homeLandmass)
    {
      unit bestCp = null;
      var bestCpD = 0f;
      unit bestCap = null;
      var bestCapD = 0f;
      var cand = 0;

      var cps = ControlPointManager.Instance.GetAllControlPoints();
      for (var i = 0; i < cps.Count; i++)
      {
        OpUnits++;
        var cu = cps[i].Unit;
        if (cu == null || GetOwningPlayer(cu) == p || IsUnitAlly(cu, p) || IsUncapturable(cu) || IsBlacklisted(pid, cu))
        {
          continue; // v28: invulnerable / Neutral-Passive CPs can't be taken; v31: nor ones we got stuck on
        }

        if (_clock < 600f && IsEnemyCp(cu, p))
        {
          continue; // v34: the fallback respects the 10-min lock on player-owned CPs too
        }

        var cx = GetUnitX(cu);
        var cy = GetUnitY(cu);
        if (homeLandmass >= 0 && Geography.Landmass(cx, cy) != homeLandmass)
        {
          continue;
        }

        cand++;
        var dx = cx - ax;
        var dy = cy - ay;
        var d = dx * dx + dy * dy;
        if (bestCp == null || d < bestCpD)
        {
          bestCpD = d;
          bestCp = cu;
        }
      }

      var caps = CapitalManager.GetAll();
      for (var i = 0; i < caps.Count; i++)
      {
        OpUnits++;
        var cu = caps[i].Unit;
        if (cu == null || GetUnitState(cu, UNIT_STATE_LIFE) <= 0.405f
            || GetOwningPlayer(cu) == p || IsUnitAlly(cu, p))
        {
          continue;
        }

        var cx = GetUnitX(cu);
        var cy = GetUnitY(cu);
        if (homeLandmass >= 0 && Geography.Landmass(cx, cy) != homeLandmass)
        {
          continue;
        }

        cand++;
        var dx = cx - ax;
        var dy = cy - ay;
        var d = dx * dx + dy * dy;
        if (bestCap == null || d < bestCapD)
        {
          bestCapD = d;
          bestCap = cu;
        }
      }

      Cand[pid] = cand;
      return bestCp != null ? bestCp : bestCap;
    }

    // Rule 0 (v29 rewrite): the most-threatened owned anchor (capital or control point), or null.
    // An anchor counts as threatened only if BOTH hold:
    //   1. it is DAMAGED (HP below DamagedFraction of max). WL gives owned CPs regeneration, so this means
    //      "something hit it recently". Undamaged anchors cost one HP read -- no unit enumeration at all,
    //      which removes the per-CP range scan that dominated the combat-tick load.
    //   2. more than DefendThreshold units of ENEMY PLAYERS stand near it on walkable ground.
    // Never counted: neutrals (creeps, critters, the ~1900 preplaced Neutral-Passive rescue units that sit next
    // to many CPs), allies, structures, and anything on unwalkable terrain (ships offshore, flyers over sea) --
    // an army attack-moved toward those can't reach them and just stands at the coast.
    // 0.43.2: only what the army at (ax, ay) can reach -- its landmass, and within AiDefense.DefendReach (an own
    // capital on that landmass at any distance). Before: any damaged own CP on the whole map.
    internal static unit FindDefenseTarget(player p, float ax, float ay)
    {
      unit best = null;
      var worst = 0;
      _defCreeps = 0;
      var armyLm = Geography.Landmass(ax, ay);

      var caps = CapitalManager.GetAll();
      for (var i = 0; i < caps.Count; i++)
      {
        var cu = caps[i].Unit;
        if (cu == null || GetOwningPlayer(cu) != p || !IsDamaged(cu) || !DefendableFrom(cu, ax, ay, armyLm, true))
        {
          continue;
        }

        var n = CountEnemiesNear(p, GetUnitX(cu), GetUnitY(cu));
        if (n > DefendThreshold && n > worst)
        {
          worst = n;
          best = cu;
          _defCreeps = _lastCreepCount;
        }
      }

      var mine = p.GetPlayerData().ControlPoints;
      for (var i = 0; i < mine.Count; i++)
      {
        var cu = mine[i].Unit;
        if (cu == null || !IsDamaged(cu) || !DefendableFrom(cu, ax, ay, armyLm, false))
        {
          continue;
        }

        var n = CountEnemiesNear(p, GetUnitX(cu), GetUnitY(cu));
        if (n > DefendThreshold && n > worst)
        {
          worst = n;
          best = cu;
          _defCreeps = _lastCreepCount;
        }
      }

      _defWorst = worst;
      return best;
    }

    private static bool DefendableFrom(unit cu, float ax, float ay, int armyLm, bool capital)
    {
      var x = GetUnitX(cu);
      var y = GetUnitY(cu);
      var lm = Geography.Landmass(x, y);
      if (armyLm >= 0 && lm >= 0 && lm != armyLm)
      {
        return false;
      }

      var dx = x - ax;
      var dy = y - ay;
      return capital || dx * dx + dy * dy <= AiDefense.DefendReach * AiDefense.DefendReach;
    }

    private static bool IsDamaged(unit u)
    {
      var max = GetUnitState(u, UNIT_STATE_MAX_LIFE);
      return max > 0f && GetUnitState(u, UNIT_STATE_LIFE) < max * DamagedFraction;
    }

    // Enemy-PLAYER ground units near (x,y). _lastCreepCount = neutral units that were seen and ignored
    // (diagnostics only: shows how often the old rule would have recalled the army for nothing).
    internal static int CountEnemiesNear(player p, float x, float y)
    {
      var n = 0;
      _lastCreepCount = 0;
      var g = CreateGroup();
      GroupEnumUnitsInRange(g, x, y, DefendRadius, null);
      unit u;
      while ((u = FirstOfGroup(g)) != null)
      {
        GroupRemoveUnit(g, u);
        OpUnits++;
        DefOps++;
        if (GetUnitState(u, UNIT_STATE_LIFE) <= 0.405f || IsUnitType(u, UNIT_TYPE_STRUCTURE))
        {
          continue;
        }

        var owner = GetOwningPlayer(u);
        if (GetPlayerId(owner) >= 24)
        {
          _lastCreepCount++;
          continue; // neutral: never a reason to recall
        }

        if (owner == p || IsUnitAlly(u, p) || !IsPlayerEnemy(owner, p))
        {
          continue;
        }

        // IsTerrainPathable returns TRUE when the point is NOT walkable (WC3's inverted API): deep water / cliffs.
        if (IsTerrainPathable(GetUnitX(u), GetUnitY(u), PATHING_TYPE_WALKABILITY))
        {
          continue;
        }

        // 0.42.1: enemies that cannot walk here (other area, no open edge -- e.g. across the closed Thandol bridge) are
        // no reason to recall the army: both sides stood at the banks and shot across.
        if (!AiRoutes.Reachable(x, y, GetUnitX(u), GetUnitY(u)))
        {
          continue;
        }

        n++;
      }

      DestroyGroup(g);
      return n;
    }

    // An owned capital/CP sits on real terrain, so it reads a valid landmass even when the army centroid
    // falls in an uncovered grid cell. Falls back to the army's own landmass.
    private static int HomeLandmass(player p, int fallback)
    {
      var caps = CapitalManager.GetAll();
      for (var i = 0; i < caps.Count; i++)
      {
        var cu = caps[i].Unit;
        if (cu != null && GetOwningPlayer(cu) == p && GetUnitState(cu, UNIT_STATE_LIFE) > 0.405f)
        {
          var l = Geography.Landmass(GetUnitX(cu), GetUnitY(cu));
          if (l >= 0)
          {
            return l;
          }
        }
      }

      var mine = p.GetPlayerData().ControlPoints;
      for (var i = 0; i < mine.Count; i++)
      {
        var cu = mine[i].Unit;
        if (cu != null)
        {
          var l = Geography.Landmass(GetUnitX(cu), GetUnitY(cu));
          if (l >= 0)
          {
            return l;
          }
        }
      }

      return fallback;
    }

    // Re-issue attack-move only when the destination moved a lot or the heartbeat elapsed -- avoids the
    // stop-and-go stutter from constant re-issuing. Works for a unit target (pass its x/y) or a waypoint.
    // 0.41: whole = defence / kill target / hold (every unit); otherwise AiArmy sends an attack group (smart mode).
    // 0.42: (x, y) = where to go now (a waypoint or the target), (fx, fy) = the final target (group size, staging).
    private static void IssueAttackToPoint(player p, int pid, float x, float y, bool whole, float fx, float fy)
    {
      var moved = !LastPtX.ContainsKey(pid)
        || (x - LastPtX[pid]) * (x - LastPtX[pid]) + (y - LastPtY[pid]) * (y - LastPtY[pid]) > 300f * 300f;
      var recent = LastIssueTime.ContainsKey(pid) && _clock - LastIssueTime[pid] <= HeartbeatEvery;
      if (!moved && recent)
      {
        return;
      }

      if (AiArmy.Smart)
      {
        AiArmy.Attack(p, pid, x, y, moved, whole, fx, fy); // 0.41: attack group, rest at the staging CP, idle-and-away
      }
      else
      {
        AttackMove(p, x, y, !moved && OrdersIdleOnly); // 0.39: same target -> only idle units
      }

      LastPtX[pid] = x;
      LastPtY[pid] = y;
      LastIssueTime[pid] = _clock;
    }

    // v15: walk the authored graph. Return the CP where I own one end of an edge but not the other
    // (my frontier), nearest to my anchor. Owning both ends = captured -> that edge is skipped, so the front
    // advances naturally; unfilled (0) ids and unresolved CPs are ignored. Null -> fall back to the picker.
    // v28: writes frontier counts into d (diagnostics only) and skips uncapturable (invulnerable) frontiers.
    private static unit PickGraphTarget(player p, Faction fac, float ax, float ay, BotDiag d)
    {
      d.Neutral = 0;
      d.Enemy = 0;
      d.Locked = 0;
      d.Invuln = 0;
      d.Closed = 0;
      d.NoCp = 0;
      d.Skipped = 0;
      d.Stuck = 0;
      d.Sticky = 0;
      var setName = _factionEdgeSet.ContainsKey(fac.Name)
        ? _factionEdgeSet[fac.Name]
        : ResolveEdgeSet(fac, p);
      // v34: until the Legion summon every faction walks its own continent's graph. The summon MERGES the graphs
      // (event): from then on everyone walks the whole world, but frontiers on the faction's HOME graph (the one
      // it walked before the merge) always come first -- foreign ones only once home has none left.
      // 0.38: Old Gods walk the whole world once their rift is open (home = Kalimdor still comes first)
      var riftAll = setName != null && GateOpen("oldgods") && AiConfig.OldGodsFactions.Contains(fac.Name);
      var useName = (_graphMerged || riftAll) && setName != null ? "All" : setName;
      d.EdgeSet = setName == null ? "none" : (_graphMerged ? "All(home " + setName + ")" : setName);
      var edges = useName != null ? AiGraph.EdgesByName(useName) : null;
      if (edges == null || edges.Count == 0)
      {
        return null;
      }

      var home = _graphMerged ? NodeSetOf(setName) : null;

      // v31: one best candidate, ranked by (goal hops, weighted distance).
      //  * before 10 min: neutral frontiers only (enemy CPs are locked below).
      //  * after 10 min: whichever is closer to the ARMY, with neutral CPs weighted NeutralBias closer
      //    (keeps the "healthy" v29 movement: no marching past an adjacent enemy CP to reach a far neutral one).
      //  * a faction with an AiConfig.Goals entry (Legion -> Nordrassil) first minimises graph hops to that goal,
      //    so it advances CP-by-CP along the shortest route instead of wandering.
      var pid = GetPlayerId(p);
      var goalHops = GoalHopsFor(fac.Name, useName, p);
      unit best = null;
      var bestForeign = 0;
      var bestHops = 0;
      var bestScore = 0f;
      // 0.36: stickiness -- the frontier we are already marching on (if it is still a valid candidate)
      var current = Committed.ContainsKey(pid) ? Committed[pid] : null;
      var curFound = false;
      var curForeign = 0;
      var curHops = 0;
      var curScore = 0f;
      for (var i = 0; i < edges.Count; i++)
      {
        var a = edges[i].A;
        var b = edges[i].B;
        if (a == 0 || b == 0)
        {
          continue;
        }

        var ca = SafeCp(a);
        var cb = SafeCp(b);
        if (ca == null || cb == null)
        {
          d.NoCp++;
          continue;
        }

        var ownA = GetOwningPlayer(ca.Unit) == p || IsUnitAlly(ca.Unit, p);
        var ownB = GetOwningPlayer(cb.Unit) == p || IsUnitAlly(cb.Unit, p);
        unit frontier = null;
        if (ownA && !ownB)
        {
          frontier = cb.Unit;
        }
        else if (ownB && !ownA)
        {
          frontier = ca.Unit;
        }

        if (frontier == null)
        {
          continue;
        }

        // conditional edges: not yet time-open, or behind a closed gate -> skip until they open.
        // (checked after the frontier test so d.Closed only counts edges that would otherwise be usable)
        if (edges[i].OpenTime > _clock || (edges[i].Gate != "" && !GateOpen(edges[i].Gate)))
        {
          d.Closed++;
          continue;
        }

        // 0.39.7: Argus belongs to the Legion until the summon -- the Scourge took Antoran early (weight alone did not help)
        if (fac.Name != "Legion" && !GateOpen("legion") && AiGraph.ArgusNodes.Contains(GetUnitTypeId(frontier)))
        {
          d.Skipped++;
          continue;
        }

        // skip nodes: walk past them (they stay a waypoint) but never pick them as a capture target.
        if (AiGraph.SkipNodes.Contains(GetUnitTypeId(frontier)))
        {
          d.Skipped++;
          continue;
        }

        // v28: Neutral-Passive CPs are made invulnerable by WL (quest-locked). Attack-move ignores them and they
        // can't be damaged, so a bot that picks one parks beside it forever. Never a target.
        if (IsUncapturable(frontier))
        {
          d.Invuln++;
          continue;
        }

        var enemy = IsEnemyCp(frontier, p);

        // v26: before 10 min only neutral CPs are valid targets; enemy CPs unlock at the 10-min mark.
        if (_clock < 600f && enemy)
        {
          d.Locked++;
          continue;
        }

        // v31: a frontier this bot gave up on (stuck detection) is skipped until its blacklist expires.
        if (IsBlacklisted(pid, frontier))
        {
          d.Stuck++;
          continue;
        }

        if (enemy)
        {
          d.Enemy++;
        }
        else
        {
          d.Neutral++;
        }

        var score = TravelDist2(ax, ay, GetUnitX(frontier), GetUnitY(frontier)); // 0.35.2: portal-aware
        score = score * edges[i].Weight * edges[i].Weight;                       // 0.35.3: edge weight
        if (!enemy)
        {
          score = score * NeutralBias * NeutralBias;
        }

        var fid = GetUnitTypeId(frontier);
        var hops = 0;
        if (goalHops != null)
        {
          hops = goalHops.ContainsKey(fid) ? goalHops[fid] : 999;
        }

        // home-first (after the merge); a goal route (Legion -> Nordrassil) overrides it
        var foreign = home != null && goalHops == null && !home.Contains(fid) ? 1 : 0;
        if (frontier == current && !curFound)
        {
          curFound = true;
          curForeign = foreign;
          curHops = hops;
          curScore = score;
        }

        if (best == null || foreign < bestForeign
            || (foreign == bestForeign && (hops < bestHops || (hops == bestHops && score < bestScore))))
        {
          best = frontier;
          bestForeign = foreign;
          bestHops = hops;
          bestScore = score;
        }
      }

      // 0.36: keep the current target unless the new best is in a better class (home/goal hops) or clearly closer.
      // Without this, a moving army flipped between two similar frontiers every service (85-min test).
      if (curFound && best != current && curForeign == bestForeign && curHops == bestHops
          && bestScore >= curScore * StickySwitch)
      {
        d.Sticky++;
        return current;
      }

      return best;
    }

    // 0.35.2: squared travel distance army -> target. Straight line on the same landmass. To a target on another
    // landmass, the best AI portal whose one end is on the army's landmass counts as the way: |army->portal| +
    // |other end->target|. Before, a target across the sea that LOOKED close (Blasted Lands from Argus) beat the
    // real way out (the Northrend portal), so the Legion sat in Argus. Full path-based targeting: TODO.md.
    private static float TravelDist2(float ax, float ay, float tx, float ty)
    {
      var dx = tx - ax;
      var dy = ty - ay;
      var direct = dx * dx + dy * dy;
      var lmA = Geography.Landmass(ax, ay);
      var lmT = Geography.Landmass(tx, ty);
      if (lmA < 0 || lmA == lmT)
      {
        return direct;
      }

      var best = -1f;
      for (var i = 0; i < AiLegion.PortalPairCount; i++)
      {
        var a = AiLegion.PortalA(i);
        var b = AiLegion.PortalB(i);
        if (GetUnitTypeId(a) == 0 || GetUnitTypeId(b) == 0)
        {
          continue;
        }

        var d = PortalLeg(ax, ay, tx, ty, a, b, lmA);
        if (d >= 0f && (best < 0f || d < best))
        {
          best = d;
        }

        d = PortalLeg(ax, ay, tx, ty, b, a, lmA);
        if (d >= 0f && (best < 0f || d < best))
        {
          best = d;
        }
      }

      if (best < 0f)
      {
        return direct;
      }

      return best * best;
    }

    // army -> entry (must be on the army's landmass) -> exit -> target; -1 if the entry is elsewhere
    private static float PortalLeg(float ax, float ay, float tx, float ty, unit entry, unit exit, int lmA)
    {
      var ex = GetUnitX(entry);
      var ey = GetUnitY(entry);
      if (Geography.Landmass(ex, ey) != lmA)
      {
        return -1f;
      }

      var ox = GetUnitX(exit);
      var oy = GetUnitY(exit);
      return SquareRoot((ex - ax) * (ex - ax) + (ey - ay) * (ey - ay))
             + SquareRoot((tx - ox) * (tx - ox) + (ty - oy) * (ty - oy));
    }

    // v34: graph merge (set at the Legion summon) and node sets per edge-set name (built once).
    public static bool GraphMerged => _graphMerged;
    internal static bool _graphMerged;

    private static HashSet<int> NodeSetOf(string setName)
    {
      if (setName == null)
      {
        return null;
      }

      if (AiState.NodeSets.ContainsKey(setName))
      {
        return AiState.NodeSets[setName];
      }

      var set = new HashSet<int>();
      var edges = AiGraph.EdgesByName(setName);
      if (edges != null)
      {
        for (var i = 0; i < edges.Count; i++)
        {
          set.Add(edges[i].A);
          set.Add(edges[i].B);
        }
      }

      AiState.NodeSets[setName] = set;
      return set;
    }

    // v31: hop distance from every node to the faction's goal CP over its current edge set (all edges, open or
    // not -- topology only). Cached per (set, goal). Null when the faction has no goal, the goal isn't in this
    // edge set, or the faction (or an ally) already owns it.

    private static Dictionary<int, int> GoalHopsFor(string facName, string setName, player p)
    {
      if (setName == null || !AiConfig.Goals.ContainsKey(facName))
      {
        return null;
      }

      var goal = AiConfig.Goals[facName];
      var gcp = SafeCp(goal);
      if (gcp != null && (GetOwningPlayer(gcp.Unit) == p || IsUnitAlly(gcp.Unit, p)))
      {
        return null; // goal reached -> normal expansion
      }

      var key = setName + "|" + I2S(goal);
      if (AiState.GoalHopCache.ContainsKey(key))
      {
        return AiState.GoalHopCache[key];
      }

      var edges = AiGraph.EdgesByName(setName);
      var hops = new Dictionary<int, int>();
      var queue = new List<int>();
      var inSet = false;
      for (var i = 0; i < edges.Count && !inSet; i++)
      {
        inSet = edges[i].A == goal || edges[i].B == goal;
      }

      if (inSet)
      {
        hops[goal] = 0;
        queue.Add(goal);
        for (var qi = 0; qi < queue.Count; qi++) // BFS; list-as-queue, never iterates a Dictionary
        {
          var cur = queue[qi];
          var next = hops[cur] + 1;
          for (var i = 0; i < edges.Count; i++)
          {
            var other = edges[i].A == cur ? edges[i].B : edges[i].B == cur ? edges[i].A : 0;
            if (other != 0 && !hops.ContainsKey(other))
            {
              hops[other] = next;
              queue.Add(other);
            }
          }
        }
      }

      var result = inSet ? hops : null;
      AiState.GoalHopCache[key] = result;
      return result;
    }

    // ---- v31 stuck detection -------------------------------------------------------------------------------
    // If a bot keeps the same capture target for StuckSec and the target neither changed owner nor lost HP
    // (army can't reach it, can't hurt it, keeps losing), the bot gives up on it for BlacklistSec. Catches
    // every "parked forever" cause at once: unreachable islands, blocked bridges, invulnerable CPs, etc.
    private const float StuckSec = 240f;
    private const float BlacklistSec = 300f;

    private static void TrackStuck(player p, int pid, unit tgt)
    {
      if (tgt == null)
      {
        AiState.StuckTarget[pid] = null;
        return;
      }

      var hp = GetUnitState(tgt, UNIT_STATE_LIFE);
      var owner = GetOwningPlayer(tgt);
      var same = AiState.StuckTarget.ContainsKey(pid) && AiState.StuckTarget[pid] == tgt && AiState.StuckOwner[pid] == owner;
      if (!same)
      {
        AiState.StuckTarget[pid] = tgt;
        AiState.StuckSince[pid] = _clock;
        AiState.StuckHp[pid] = hp;
        AiState.StuckOwner[pid] = owner;
        return;
      }

      if (hp < AiState.StuckHp[pid] * 0.9f)
      {
        AiState.StuckSince[pid] = _clock; // real progress -> reset the timer
        AiState.StuckHp[pid] = hp;
        return;
      }

      if (_clock - AiState.StuckSince[pid] < StuckSec)
      {
        return;
      }

      if (!AiState.BlackUnits.ContainsKey(pid))
      {
        AiState.BlackUnits[pid] = new List<unit>();
        AiState.BlackUntil[pid] = new List<float>();
      }

      // 0.37.2: back-off -- every repeat on the same target doubles the skip (5, 10, 20 min max). Dwarves kept
      // returning to the closed Thandol bridge every 9 min (4 stuck + 5 skipped).
      if (!AiState.StuckCount.ContainsKey(pid))
      {
        AiState.StuckCount[pid] = new Dictionary<unit, int>();
      }

      var repeats = AiState.StuckCount[pid].ContainsKey(tgt) ? AiState.StuckCount[pid][tgt] : 0;
      AiState.StuckCount[pid][tgt] = repeats + 1;
      var skip = BlacklistSec * (repeats >= 2 ? 4f : (repeats == 1 ? 2f : 1f));
      AiState.BlackUnits[pid].Add(tgt);
      AiState.BlackUntil[pid].Add(_clock + skip);
      AiState.StuckTarget[pid] = null;
      Log("P" + I2S(pid) + " " + FacName(p) + ": STUCK on " + GetUnitName(tgt) + " for "
          + I2S(R2I(StuckSec)) + "s, no progress -> skip it for " + I2S(R2I(skip)) + "s");
    }

    internal static bool IsBlacklisted(int pid, unit cp)
    {
      if (!AiState.BlackUnits.ContainsKey(pid))
      {
        return false;
      }

      var us = AiState.BlackUnits[pid];
      var ts = AiState.BlackUntil[pid];
      for (var i = us.Count - 1; i >= 0; i--)
      {
        if (ts[i] <= _clock)
        {
          us.RemoveAt(i);
          ts.RemoveAt(i);
        }
        else if (us[i] == cp)
        {
          return true;
        }
      }

      return false;
    }

    // v28: a CP nobody can capture right now -- owned by Neutral Passive (WL makes those invulnerable) or
    // invulnerable for any other reason. Public so AiDebug's graph audit uses the exact same test.
    public static bool IsUncapturable(unit cp)
    {
      return GetOwningPlayer(cp) == Player(PLAYER_NEUTRAL_PASSIVE) || BlzIsUnitInvulnerable(cp);
    }

    // A frontier is "enemy" only if a live bot/human owns it (and isn't our ally). Neutral/unowned CPs are not.
    // v30: the neutral players (24..27) ALSO report PLAYER_SLOT_STATE_PLAYING, so before this check every
    // creep-held CP counted as an "enemy" frontier: locked before 10 min (the graph found nothing -> every bot
    // ran on the fallback picker) and pushed through the muster/clash yo-yo after 10 min in older builds.
    // An enemy CP must belong to a real player slot (0..23).
    internal static bool IsEnemyCp(unit cp, player p)
    {
      var owner = GetOwningPlayer(cp);
      return owner != p
             && GetPlayerId(owner) < 24
             && IsActive(owner)
             && !IsPlayerAlly(p, owner);
    }

    // 0.39.2: a slot that plays: a playing human / computer, or a slot whose human left and the AI took over
    internal static bool IsActive(player p)
    {
      return GetPlayerSlotState(p) == PLAYER_SLOT_STATE_PLAYING || AiState.TakenOver.Contains(GetPlayerId(p));
    }

    internal static bool OwnsCp(WaveConfig cfg, int cpId)
    {
      if (cpId == 0)
      {
        return false;
      }

      var cp = SafeCp(cpId);
      if (cp == null)
      {
        return false;
      }

      var owner = GetOwningPlayer(cp.Unit);
      if (GetPlayerId(owner) >= 24)
      {
        return false;
      }

      var f = owner.GetPlayerData().Faction;
      return f != null && AiWaveRunner.InGroup(cfg, f.Name);
    }

    internal static void Announce(string msg)
    {
      for (var i = 0; i < 24; i++)
      {
        DisplayTimedTextToPlayer(Player(i), 0, 0, 12, msg);
      }
    }

    // Bright flashing minimap ping (visible to everyone) so a big event isn't missed.
    internal static void PingAt(float x, float y)
    {
      PingMinimapEx(x, y, 6f, 255, 40, 40, true);
      PingMinimapEx(x, y, 8f, 255, 0, 255, true); // second, offset-colour ping = "double ping"
    }

    // v34.2: run one wave-tick subtask; an error is logged (once per subtask) instead of aborting the tick.

    internal static void Safe(string name, System.Action task)
    {
      TaskRing[TaskRingPos] = TimeTag(_clock) + " " + name; // 0.39: freeze diagnosis (heartbeat file)
      TaskRingPos = (TaskRingPos + 1) % TaskRing.Length;
      try
      {
        task();
      }
      catch (System.Exception e)
      {
        TickError(name, e);
      }
    }

    private static void TickError(string name, System.Exception e)
    {
      if (!AiState.TickErrors.Contains(name))
      {
        AiState.TickErrors.Add(name);
        LogPin("TICK ERROR in " + name + ": " + e.Message);
      }
    }

    // 0.40: the old 15-s wave tick, split into scheduler tasks (one per odd slot of the 15-s cycle, same order).
    // v34.2 still holds: every subtask runs isolated (SimpleBot.Safe via the scheduler) -- gates first; a failure is
    // written once to the pinned log ("TICK ERROR in ...") and never stops the others. Skipped during -botbreak.
    private static void RegisterWaveTasks()
    {
      var k = 0;
      AiScheduler.AddWave(k++, "wave cycle start", BeginWaveCycle);
      AiScheduler.AddWave(k++, "destructible gates", AiGates.SweepDestructibleGates); // v27.1: destructible gates ONCE
      AiScheduler.AddWave(k++, "gate sweep", AiGates.SweepBotGates);                  // v26: gate units
      AiScheduler.AddWave(k++, "tempest reach", AiGates.WireTempestReach);            // v25
      AiScheduler.AddWave(k++, "named gates", AiGates.OpenNamedGates);                // 0.36: "greymane", "tomb"
      AiScheduler.AddWave(k++, "old gods rift", AiGates.OpenOldGodsRift);             // 0.37
      AiScheduler.AddWave(k++, "sulfuron barracks", AiMissions.RunSulfuronBarracks);  // 0.37
      AiScheduler.AddWave(k++, "yogg release", AiMissions.RunYogg);                   // 0.38.1
      AiScheduler.AddWave(k++, "feathermoon", AiMissions.RunFeathermoon);             // 0.39
      AiScheduler.AddWave(k++, "continental outpost", AiMissions.RunContinentalOutpost); // 0.39.5
      AiScheduler.AddWave(k++, "emerald portals", AiGates.RunEmeraldPortals);         // 0.39.5
      AiScheduler.AddWave(k++, "one-shots", AiMissions.RunOneShots);                  // v25: runestones
      AiScheduler.AddWave(k++, "kill targets", AiMissions.AssignKillTargets);         // v31/v34.2
      AiScheduler.AddWave(k++, "cp grants", AiMissions.RunCpGrants);                  // v31
      AiScheduler.AddWave(k++, "starter kit", AiMissions.RunStarterKit);              // v32
      AiScheduler.AddWave(k++, "starter production", AiMissions.RunStarterProduction); // 0.39.2
      AiScheduler.AddWave(k++, "ragnaros", AiMissions.RunRagnarosMission);
      AiScheduler.AddWave(k++, "hero visits", AiHeroVisits.Run);                      // 0.35.2
      AiScheduler.AddWave(k++, "hero care", AiHeroCare.Run);                          // 0.36
      AiScheduler.AddWave(k++, "hero skills", AiHeroSkills.Run);                      // 0.38
      AiScheduler.AddWave(k++, "standings", AiStandings.Check);                       // 0.36
      AiScheduler.AddWave(k++, "palace handover", AiMissions.LegionPalaceHandover);   // v32
      AiScheduler.AddWave(k++, "banned forms", AiMissions.ScanBannedForms);           // v32
      AiScheduler.AddWave(k++, "demon portal", () => AiLegion.FixDemonPortal());      // v31
      AiScheduler.AddWave(k++, "legion check", AiLegion.CheckLegionSummoned);         // v34.1
      AiScheduler.AddWave(k++, "portal watchdog", AiLegion.PortalWatchdog);           // v34.1
      AiScheduler.AddWave(k++, "kul tiras repair", AiMissions.KulTirasRepair);        // v34.1
      AiScheduler.AddWave(k++, "waves", RunWaves);
      AiScheduler.AddWave(k, "wave cycle end", EndWaveCycle);                         // k = 28 (max 29)
    }

    private static void BeginWaveCycle()
    {
      _validCpIds = null; // v27: rebuild the valid-CP set once per cycle so SafeCp sees CPs created at runtime
      AiScheduler.TakeWaveCycleOps();
    }

    private static void RunWaves()
    {
      var waves = AiWaves.All;
      for (var w = 0; w < waves.Count; w++)
      {
        try
        {
          AiWaveRunner.RunWave(w, waves[w]);
        }
        catch (System.Exception e)
        {
          TickError("wave " + I2S(w), e);
        }
      }
    }

    // LastWaveOps / MaxWaveOps keep their meaning: the whole cycle's wave work
    private static void EndWaveCycle()
    {
      LastWaveOps = AiScheduler.TakeWaveCycleOps();
      if (LastWaveOps > MaxWaveOps)
      {
        MaxWaveOps = LastWaveOps;
      }
    }

    public static bool GateOpen(string gate) => _gateOpen.ContainsKey(gate) && _gateOpen[gate];

    // v26.1: ControlPointManager.GetFromUnitType THROWS for any id that isn't a registered control point, and
    // our authored graphs contain non-CP ids (Legion-nether zones, special leaves). This wrapper returns null
    // for those instead, so the walker/staging/objective code simply skips them. Never call the raw method.
    private static HashSet<int> _validCpIds;
    public static ControlPoint SafeCp(int id)
    {
      if (_validCpIds == null)
      {
        _validCpIds = new HashSet<int>();
        var all = ControlPointManager.Instance.GetAllControlPoints();
        for (var i = 0; i < all.Count; i++)
        {
          _validCpIds.Add(all[i].UnitType);
        }
      }

      return _validCpIds.Contains(id) ? ControlPointManager.Instance.GetFromUnitType(id) : null;
    }

    internal static void EnsureNodeSets()
    {
      if (_combinedNodes != null)
      {
        return;
      }

      _combinedNodes = new HashSet<int>();
      for (var i = 0; i < AiGraph.Combined.Count; i++)
      {
        _combinedNodes.Add(AiGraph.Combined[i].A);
        _combinedNodes.Add(AiGraph.Combined[i].B);
      }

      _kalimdorNodes = new HashSet<int>();
      for (var i = 0; i < AiGraph.Kalimdor.Count; i++)
      {
        _kalimdorNodes.Add(AiGraph.Kalimdor[i].A);
        _kalimdorNodes.Add(AiGraph.Kalimdor[i].B);
      }
    }

    // v26: pick a faction's node graph. Scourge/Legion are special-cased (Combined; Legion flips to Kalimdor
    // at the summon). Everyone else resolves by which graph holds the CPs they currently own, then caches it
    // (an invasion's DestEdgeSet later overwrites the cache). Island factions own no graph CP -> null -> the
    // generic picker, until they invade. This is why only continent factions use the CP system.
    private static string ResolveEdgeSet(Faction fac, player p)
    {
      var def = AiGraph.DefaultEdgeSet(fac.Name, _clock);
      if (def != null)
      {
        return def;
      }

      EnsureNodeSets();
      var cc = 0;
      var kc = 0;
      var cps = ControlPointManager.Instance.GetAllControlPoints();
      for (var i = 0; i < cps.Count; i++)
      {
        if (GetOwningPlayer(cps[i].Unit) != p)
        {
          continue;
        }

        var t = cps[i].UnitType;
        if (_combinedNodes.Contains(t))
        {
          cc++;
        }
        else if (_kalimdorNodes.Contains(t))
        {
          kc++;
        }
      }

      if (cc == 0 && kc == 0)
      {
        return null; // no foothold on either graph yet
      }

      var name = kc > cc ? "Kalimdor" : "Combined";
      _factionEdgeSet[fac.Name] = name;
      Log(fac.Name + ": edge set resolved -> " + name + " (owns " + I2S(cc) + " Combined / " + I2S(kc) + " Kalimdor CPs)");
      return name;
    }

    internal static unit FindUnitOfType(int typeId, float x, float y, float r)
    {
      var g = CreateGroup();
      GroupEnumUnitsInRange(g, x, y, r, null);
      unit found = null;
      unit u;
      while ((u = FirstOfGroup(g)) != null)
      {
        GroupRemoveUnit(g, u);
        if (found == null && GetUnitTypeId(u) == typeId)
        {
          found = u;
        }
      }

      DestroyGroup(g);
      return found;
    }

    internal static void FloatLabel(string text, float x, float y)
    {
      var tt = CreateTextTag();
      SetTextTagText(tt, text, 0.023f);
      SetTextTagPos(tt, x, y, 128f);
      SetTextTagColor(tt, 255, 90, 90, 255);
      SetTextTagVisibility(tt, true);
      SetTextTagPermanent(tt, true);
    }

    // v24: heroes auto-claim ground items within 1000 range. Called only for a bot's own heroes during that
    // bot's combat pass (a handful of units, once per ~6.5s) -> no timer, effectively free. One reused rect.
    private static void HeroGrabItems(unit h)
    {
      if (UnitInventorySize(h) <= 0)
      {
        return;
      }

      if (_itemRect == null)
      {
        _itemRect = Rect(0f, 0f, 1f, 1f);
      }

      var x = GetUnitX(h);
      var y = GetUnitY(h);
      SetRect(_itemRect, x - 1000f, y - 1000f, x + 1000f, y + 1000f);
      _grabHero = h;
      EnumItemsInRect(_itemRect, null, GrabItemEnum);
    }

    private static void GrabItemEnum()
    {
      var it = GetEnumItem();
      if (it == null || _grabHero == null || GetWidgetLife(it) <= 0.405f || IsItemOwned(it))
      {
        return;
      }

      UnitAddItem(_grabHero, it); // fails harmlessly when the inventory is full or the item isn't carriable
    }

    internal static player PlayerOfFaction(string name)
    {
      for (var i = 0; i < 24; i++)
      {
        var p = Player(i);
        var f = p.GetPlayerData().Faction;
        if (f != null && f.Name == name)
        {
          return p;
        }
      }

      return null;
    }

    // 0.35: the AI controls this slot, AND it gets the bot bonuses (gold subsidy, free techs/upgrades, free hero
    // revives, starter kit, scripted missions, waves). False for an autopilot player in a FAIR build
    // (AiDebug.Access == Off): the AI then only plays the faction with its own resources.
    internal static bool HasPerks(player p)
    {
      return IsBot(p) && (!AiState.Autopilot.Contains(GetPlayerId(p)) || AiDebug.Access != AiDebug.CommandAccess.Off);
    }

    // 0.35: autopilot -- a human slot joins / leaves the bot list
    internal static void AddBot(player p)
    {
      var i = GetPlayerId(p);
      if (IsBot(p))
      {
        return;
      }

      Bots.Add(p);
      Committed[i] = null;
      CommitTime[i] = 0f;
      Cand[i] = 0;
    }

    internal static void RemoveBot(player p)
    {
      // 0.35.2: by player id, not by object -- make sure the slot really leaves the bot list
      var id = GetPlayerId(p);
      for (var i = Bots.Count - 1; i >= 0; i--)
      {
        if (GetPlayerId(Bots[i]) == id)
        {
          Bots.RemoveAt(i);
        }
      }
    }

    internal static bool IsBot(player p)
    {
      for (var i = 0; i < Bots.Count; i++)
      {
        if (Bots[i] == p)
        {
          return true;
        }
      }

      return false;
    }

    // A scripted step still needs work if an enemy army is near it, OR a CP/capital near it isn't yet mine.
    private static bool AreaNeedsAttention(player p, float x, float y, float radius)
    {
      var g = CreateGroup();
      GroupEnumUnitsInRange(g, x, y, radius, null);
      unit u;
      var army = false;
      while ((u = FirstOfGroup(g)) != null)
      {
        GroupRemoveUnit(g, u);
        OpUnits++;
        if (!army && GetOwningPlayer(u) != p && !IsUnitAlly(u, p)
            && GetUnitState(u, UNIT_STATE_LIFE) > 0.405f && !IsUnitType(u, UNIT_TYPE_STRUCTURE))
        {
          army = true;
        }
      }

      DestroyGroup(g);
      if (army)
      {
        return true;
      }

      var cps = ControlPointManager.Instance.GetAllControlPoints();
      for (var i = 0; i < cps.Count; i++)
      {
        var cu = cps[i].Unit;
        if (cu == null || GetOwningPlayer(cu) == p || IsUnitAlly(cu, p))
        {
          continue;
        }

        var dx = GetUnitX(cu) - x;
        var dy = GetUnitY(cu) - y;
        if (dx * dx + dy * dy <= radius * radius)
        {
          return true;
        }
      }

      var caps = CapitalManager.GetAll();
      for (var i = 0; i < caps.Count; i++)
      {
        var cu = caps[i].Unit;
        if (cu == null || GetUnitState(cu, UNIT_STATE_LIFE) <= 0.405f
            || GetOwningPlayer(cu) == p || IsUnitAlly(cu, p))
        {
          continue;
        }

        var dx = GetUnitX(cu) - x;
        var dy = GetUnitY(cu) - y;
        if (dx * dx + dy * dy <= radius * radius)
        {
          return true;
        }
      }

      return false;
    }

    // 0.41: -orders idle|all (the old modes, for A/B tests). Uses the army collected by Process (no second pass).
    private static void AttackMove(player p, float tx, float ty, bool idleOnly)
    {
      for (var i = 0; i < AiArmy.Units.Count; i++)
      {
        var u = AiArmy.Units[i];
        if (!idleOnly || GetUnitCurrentOrder(u) == 0)
        {
          OpOrders++;
          OrdersIssued++;
          AiScheduler.CountOrder(u, tx, ty); // 0.40: distance bucket, idle at target
          IssuePointOrder(u, "attack", tx, ty);
        }
      }
    }

    private static void Gather(player p, float ax, float ay)
    {
      for (var i = 0; i < AiArmy.Units.Count; i++)
      {
        var u = AiArmy.Units[i];
        OpOrders++;
        OrdersIssued++;
        AiScheduler.CountOrder(u, ax, ay); // 0.40
        IssuePointOrder(u, "attack", ax, ay); // v12: fight to the rally point, not walk blindly
      }
    }

    // 0.41: "smart" (AiArmy), "idle" or "all" (the old modes) -- shown in -dump UNITS and the heartbeat
    internal static string OrdersMode() => AiArmy.Smart ? "smart" : (OrdersIdleOnly ? "idle" : "all");
  }

  // v28: per-bot diagnostics, written by SimpleBot.Process, read by AiDebug. Display only.
  public sealed class BotDiag
  {
    public string EdgeSet = "-";
    public int Neutral;      // capturable neutral frontiers found this service
    public int Enemy;        // capturable enemy frontiers (after the 10-min lock)
    public int Locked;       // enemy frontiers skipped because t < 10 min
    public int Invuln;       // frontiers skipped as uncapturable (Neutral Passive / invulnerable)
    public int Closed;       // frontiers behind a not-yet-open time edge or closed named gate
    public int Skipped;      // frontiers that are SkipNodes
    public int NoCp;         // edges with an id that isn't a registered control point
    public int Stuck;        // v31: frontiers skipped because this bot gave up on them (stuck blacklist)
    public int Sticky;       // 0.36: 1 = the current target was kept although another frontier scored better
    public int AnchorUnits;  // 0.36: units in the group the target anchor is taken from (biggest landmass group)
    public bool Saving;      // 0.38: last production turn saved gold for an available hero (no units)
    public unit Target;      // current objective unit (null = point/none)
    public string Reason = "-";
    public float TargetSince;
    public float AnchorX;
    public float AnchorY;
    public bool AnchorIsBase;
    public int HomeLm = -999;
  }

  // v28: one wave's gate status, built on demand by AiWaveRunner.GetWaveDiag.
  public sealed class WaveDiag
  {
    public int Phase;        // 0 idle, 1 gather, 2 channel
    public float PhaseAge;
    public float CooldownLeft;
    public bool HomeOk;
    public int HomeLm;
    public int Owned;
    public int Total;
    public int Need;
    public bool Monuments;
    public int Enemies;
    public bool TriggerOk;
    public bool Active;
    public bool HasBot;      // v30: false -> wave disabled (no bot plays any faction of the group)
  }

  // 0.34.4: runtime collections of SimpleBot, kept in their own class. CSharp.lua turns every static member of a
  // class into a Lua local of one function (limit 200) and builds initialized static fields in one static
  // constructor (about 55 upvalues). SimpleBot sits at both limits: in v34-v34.2 fields past the second limit were
  // nil (no bot attacked), and 0.34.3 crossed the first one (map would not load). New state goes here or into
  // another small class -- never into SimpleBot. tools/ai/check_refs.py checks both limits.
  internal static class AiState
  {
    internal static readonly Dictionary<string, HashSet<int>> NodeSets = new();
    internal static readonly Dictionary<string, Dictionary<int, int>> GoalHopCache = new();
    internal static readonly Dictionary<int, unit> StuckTarget = new();
    internal static readonly Dictionary<int, float> StuckSince = new();
    internal static readonly Dictionary<int, float> StuckHp = new();
    internal static readonly Dictionary<int, player> StuckOwner = new();
    internal static readonly Dictionary<int, List<unit>> BlackUnits = new();
    internal static readonly Dictionary<int, List<float>> BlackUntil = new();
    internal static readonly Dictionary<int, Dictionary<unit, int>> StuckCount = new(); // 0.37.2: repeats per target
    internal static readonly HashSet<int> TakenOver = new(); // 0.39.2: slots taken over from leaving humans
    internal static readonly HashSet<string> TickErrors = new();
    internal static readonly Dictionary<int, unit> KillTargetUnit = new();
    internal static readonly HashSet<int> KillDone = new();
    internal static readonly Dictionary<int, float> KillSince = new();
    internal static readonly HashSet<int> ClearDone = new();
    internal static readonly Dictionary<int, int> ClearActive = new();
    internal static readonly Dictionary<int, float> ClearSince = new();
    internal static readonly List<int> PairLink = new();
    internal static readonly List<unit> PairA = new();
    internal static readonly List<unit> PairB = new();
    internal static readonly HashSet<int> Autopilot = new();                 // 0.35: human pids the AI plays
    internal static readonly HashSet<unit> MissionUnits = new();             // 0.35.2: heroes on a hero visit
    internal static readonly Dictionary<int, float> AutopilotToggled = new(); // 0.35: last toggle time per pid
  }

